/*
 * Settings > App manager and Files > Install .ipa (included by ui_settings.c).
 *
 * Installed iPhone OS apps live in <touchHLE_dir>/touchHLE_apps as extracted
 * .app bundles or .ipa archives, with per-app saves in touchHLE_sandbox/<bundle_id>
 * and launcher tiles generated by /usr/sbin/n72-ios-tiles (touchHLE --n72-tiles).
 */

#define IOS_TILES	"/usr/sbin/n72-ios-tiles"
#define IOS_APPS_DIR	"/usr/share/n72-ui/apps"
#define IOS_ICONS_DIR	"/usr/share/n72-ui/icons"
#define TOUCHHLE_CMD	"n72-touchhle"

static const char *touchhle_dir(void)
{
	const char *e = getenv("N72_TOUCHHLE_DIR");

	return e && *e ? e : "/root/n72hle-test";
}

static void touchhle_apps_dir(char *out, size_t len)
{
	snprintf(out, len, "%s/touchHLE_apps", touchhle_dir());
}

static void touchhle_sandbox_dir(char *out, size_t len)
{
	snprintf(out, len, "%s/touchHLE_sandbox", touchhle_dir());
}

/* Safe single path component (no slashes, not . or .., no control chars). */
static bool safe_single_name(const char *s)
{
	if (!s || !*s || !strcmp(s, ".") || !strcmp(s, "..") || s[0] == '.')
		return false;
	for (; *s; s++) {
		unsigned char c = (unsigned char)*s;

		if (c == '/' || c < 0x20 || c == 0x7f)
			return false;
	}
	return true;
}

/* Safe CFBundleIdentifier for touchHLE_sandbox/<id> removal. */
static bool safe_bundle_id(const char *s)
{
	if (!safe_single_name(s) || strstr(s, ".."))
		return false;
	for (; *s; s++) {
		unsigned char c = (unsigned char)*s;

		if (c <= 0x20 || c >= 0x7f)
			return false;
	}
	return true;
}

/* Tile stem matching touchHLE's n72_export_tiles ("ios-" + lowercase alnum / '-'). */
static void ios_tile_id(const char *stem, char *out, size_t len)
{
	size_t o = 0;

	if (len < 6) {
		if (len)
			out[0] = 0;
		return;
	}
	memcpy(out, "ios-", 4);
	o = 4;
	for (; *stem && o + 1 < len; stem++) {
		unsigned char c = (unsigned char)*stem;

		out[o++] = isalnum(c) ? (char)tolower(c) : '-';
	}
	out[o] = 0;
}

/* ----------------------------------------------------- Info.plist parser */

struct app_plist_meta {
	char display_name[80];
	char bundle_name[80];
	char bundle_id[128];
	char short_ver[32];
	char bundle_ver[32];
};

static uint64_t plist_be(const uint8_t *p, unsigned int n)
{
	uint64_t v = 0;

	for (unsigned int i = 0; i < n; i++)
		v = (v << 8) | p[i];
	return v;
}

static bool bplist_len(const uint8_t *buf, size_t limit, size_t pos,
		       uint64_t *out_len, size_t *data_pos)
{
	unsigned int low;

	if (pos >= limit)
		return false;
	low = buf[pos] & 0x0f;
	if (low < 0x0f) {
		*out_len = low;
		*data_pos = pos + 1;
		return true;
	}
	if (pos + 1 >= limit || (buf[pos + 1] & 0xf0) != 0x10)
		return false;
	{
		unsigned int exp = buf[pos + 1] & 0x0f;
		unsigned int nb;

		if (exp > 3)
			return false;
		nb = 1u << exp;
		if (pos + 2 + nb > limit)
			return false;
		*out_len = plist_be(buf + pos + 2, nb);
		*data_pos = pos + 2 + nb;
		return true;
	}
}

static bool bplist_off(const uint8_t *buf, size_t off_table, unsigned int off_size,
		       uint64_t num_objs, uint64_t idx, size_t *out_pos)
{
	uint64_t o;

	if (idx >= num_objs)
		return false;
	o = plist_be(buf + off_table + (size_t)idx * off_size, off_size);
	if (o >= off_table)
		return false;
	*out_pos = (size_t)o;
	return true;
}

static bool bplist_str(const uint8_t *buf, size_t off_table, unsigned int off_size,
		       uint64_t num_objs, uint64_t idx, char *out, size_t cap)
{
	size_t pos, dpos;
	uint64_t n;
	uint8_t tag;

	if (!cap || !bplist_off(buf, off_table, off_size, num_objs, idx, &pos))
		return false;
	tag = buf[pos] & 0xf0;
	if (tag != 0x50 && tag != 0x60)
		return false;
	if (!bplist_len(buf, off_table, pos, &n, &dpos))
		return false;
	if (tag == 0x50) {
		size_t copy;

		if (n > off_table - dpos)
			return false;
		copy = n < cap - 1 ? (size_t)n : cap - 1;
		memcpy(out, buf + dpos, copy);
		out[copy] = 0;
		return true;
	}
	/* UTF-16BE string */
	if (n > (off_table - dpos) / 2)
		return false;
	{
		size_t o = 0;

		for (uint64_t i = 0; i < n && o + 1 < cap; i++) {
			uint16_t u = (uint16_t)plist_be(buf + dpos + (size_t)i * 2, 2);

			if (u < 0x80) {
				out[o++] = (char)u;
			} else if (u < 0x800 && o + 2 < cap) {
				out[o++] = (char)(0xc0 | (u >> 6));
				out[o++] = (char)(0x80 | (u & 0x3f));
			} else if (o + 3 < cap) {
				out[o++] = (char)(0xe0 | (u >> 12));
				out[o++] = (char)(0x80 | ((u >> 6) & 0x3f));
				out[o++] = (char)(0x80 | (u & 0x3f));
			} else {
				break;
			}
		}
		out[o] = 0;
		return true;
	}
}

static void plist_store_kv(struct app_plist_meta *m, const char *k, const char *v)
{
	if (!v || !*v)
		return;
	if (!strcmp(k, "CFBundleDisplayName"))
		snprintf(m->display_name, sizeof(m->display_name), "%s", v);
	else if (!strcmp(k, "CFBundleName"))
		snprintf(m->bundle_name, sizeof(m->bundle_name), "%s", v);
	else if (!strcmp(k, "CFBundleIdentifier"))
		snprintf(m->bundle_id, sizeof(m->bundle_id), "%s", v);
	else if (!strcmp(k, "CFBundleShortVersionString"))
		snprintf(m->short_ver, sizeof(m->short_ver), "%s", v);
	else if (!strcmp(k, "CFBundleVersion"))
		snprintf(m->bundle_ver, sizeof(m->bundle_ver), "%s", v);
}

static void plist_parse_bplist(const uint8_t *buf, size_t len, struct app_plist_meta *m)
{
	const uint8_t *tr;
	unsigned int off_size, ref_size;
	uint64_t num_objs, top_obj, off_table, count;
	size_t top_pos, dpos;

	if (len < 40 || memcmp(buf, "bplist00", 8))
		return;
	tr = buf + len - 32;
	off_size = tr[6];
	ref_size = tr[7];
	if ((off_size != 1 && off_size != 2 && off_size != 4 && off_size != 8) ||
	    (ref_size != 1 && ref_size != 2 && ref_size != 4 && ref_size != 8))
		return;
	num_objs = plist_be(tr + 8, 8);
	top_obj = plist_be(tr + 16, 8);
	off_table = plist_be(tr + 24, 8);
	if (!num_objs || top_obj >= num_objs || off_table >= len - 32)
		return;
	if (num_objs > (len - 32 - off_table) / off_size)
		return;
	if (!bplist_off(buf, (size_t)off_table, off_size, num_objs, top_obj, &top_pos))
		return;
	if ((buf[top_pos] & 0xf0) != 0xd0)
		return;
	if (!bplist_len(buf, (size_t)off_table, top_pos, &count, &dpos))
		return;
	if (count > ((size_t)off_table - dpos) / (2u * ref_size))
		return;
	for (uint64_t i = 0; i < count; i++) {
		char key[64], val[160];
		uint64_t kref = plist_be(buf + dpos + (size_t)i * ref_size, ref_size);
		uint64_t vref = plist_be(buf + dpos + (size_t)(count + i) * ref_size, ref_size);

		if (bplist_str(buf, (size_t)off_table, off_size, num_objs, kref, key, sizeof(key)) &&
		    bplist_str(buf, (size_t)off_table, off_size, num_objs, vref, val, sizeof(val)))
			plist_store_kv(m, key, val);
	}
}

static void xml_unescape(const char *src, size_t n, char *out, size_t cap)
{
	size_t i = 0, o = 0;

	while (i < n && o + 1 < cap) {
		if (src[i] == '&') {
			if (i + 5 <= n && !memcmp(src + i, "&amp;", 5)) {
				out[o++] = '&';
				i += 5;
				continue;
			}
			if (i + 4 <= n && !memcmp(src + i, "&lt;", 4)) {
				out[o++] = '<';
				i += 4;
				continue;
			}
			if (i + 4 <= n && !memcmp(src + i, "&gt;", 4)) {
				out[o++] = '>';
				i += 4;
				continue;
			}
			if (i + 6 <= n && !memcmp(src + i, "&quot;", 6)) {
				out[o++] = '"';
				i += 6;
				continue;
			}
			if (i + 6 <= n && !memcmp(src + i, "&apos;", 6)) {
				out[o++] = '\'';
				i += 6;
				continue;
			}
		}
		out[o++] = src[i++];
	}
	out[o] = 0;
}

static void plist_parse_xml(const char *s, struct app_plist_meta *m)
{
	const char *p = s;

	while ((p = strstr(p, "<key>"))) {
		const char *ks = p + 5, *ke = strstr(ks, "</key>");
		const char *vs, *ve;
		char key[64], val[160];

		if (!ke)
			break;
		xml_unescape(ks, (size_t)(ke - ks), key, sizeof(key));
		p = ke + 6;
		while (*p && isspace((unsigned char)*p))
			p++;
		if (strncmp(p, "<string>", 8))
			continue;
		vs = p + 8;
		ve = strstr(vs, "</string>");
		if (!ve)
			break;
		xml_unescape(vs, (size_t)(ve - vs), val, sizeof(val));
		plist_store_kv(m, key, val);
		p = ve + 9;
	}
}

static void plist_read_app_meta(const char *app_dir, struct app_plist_meta *m)
{
	char path[PATH_MAX];
	uint8_t *buf;
	long sz;
	FILE *f;

	memset(m, 0, sizeof(*m));
	snprintf(path, sizeof(path), "%s/Info.plist", app_dir);
	f = fopen(path, "rb");
	if (!f)
		return;
	if (fseek(f, 0, SEEK_END) || (sz = ftell(f)) <= 0 || sz > 262144 || fseek(f, 0, SEEK_SET)) {
		fclose(f);
		return;
	}
	buf = malloc((size_t)sz + 1);
	if (!buf) {
		fclose(f);
		return;
	}
	if (fread(buf, 1, (size_t)sz, f) == (size_t)sz) {
		buf[sz] = 0;
		if (sz >= 8 && !memcmp(buf, "bplist00", 8))
			plist_parse_bplist(buf, (size_t)sz, m);
		else
			plist_parse_xml((const char *)buf, m);
	}
	fclose(f);
	free(buf);
}

/* ----------------------------------------------------- ZIP .ipa inspector */

struct ipa_info {
	bool valid;
	bool has_traversal;
	bool already_installed;
	char bundle_dir[128];	/* e.g. "Spore.app" */
	char bundle_stem[128];	/* e.g. "Spore" */
	uint64_t file_bytes;
	uint64_t unpacked_bytes;
};

static uint16_t zip_le16(const uint8_t *p)
{
	return (uint16_t)(p[0] | ((uint16_t)p[1] << 8));
}

static uint32_t zip_le32(const uint8_t *p)
{
	return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
	       ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static bool zip_path_unsafe(const char *name)
{
	const char *p = name;

	if (!name || !*name || name[0] == '/')
		return true;
	while (*p) {
		const char *sl = strchr(p, '/');
		size_t n = sl ? (size_t)(sl - p) : strlen(p);

		if (n == 2 && p[0] == '.' && p[1] == '.')
			return true;
		if (!sl)
			break;
		p = sl + 1;
	}
	return false;
}

/* Inspect an .ipa archive using its ZIP Central Directory (no subprocess, <1 ms). */
static void ipa_inspect(const char *path, struct ipa_info *in)
{
	FILE *f;
	struct stat st;
	uint8_t *tail;
	uint64_t tail_off;
	size_t tail_len;
	long eocd = -1;
	uint16_t entries;
	uint32_t cd_size, cd_off;
	bool has_plist = false;

	memset(in, 0, sizeof(*in));
	if (stat(path, &st) || !S_ISREG(st.st_mode) || st.st_size < 22)
		return;
	in->file_bytes = (uint64_t)st.st_size;
	f = fopen(path, "rb");
	if (!f)
		return;
	tail_len = in->file_bytes > 65557 ? 65557 : (size_t)in->file_bytes;
	tail_off = in->file_bytes - tail_len;
	tail = malloc(tail_len);
	if (!tail) {
		fclose(f);
		return;
	}
	if (fseeko(f, (off_t)tail_off, SEEK_SET) || fread(tail, 1, tail_len, f) != tail_len) {
		free(tail);
		fclose(f);
		return;
	}
	for (long i = (long)tail_len - 22; i >= 0; i--) {
		if (tail[i] == 'P' && tail[i + 1] == 'K' &&
		    tail[i + 2] == 5 && tail[i + 3] == 6 &&
		    (size_t)zip_le16(tail + i + 20) == tail_len - (size_t)i - 22) {
			eocd = i;
			break;
		}
	}
	if (eocd < 0) {
		free(tail);
		fclose(f);
		return;
	}
	entries = zip_le16(tail + eocd + 10);
	cd_size = zip_le32(tail + eocd + 12);
	cd_off = zip_le32(tail + eocd + 16);
	free(tail);
	if ((uint64_t)cd_off + cd_size > in->file_bytes || fseeko(f, (off_t)cd_off, SEEK_SET)) {
		fclose(f);
		return;
	}
	for (uint16_t i = 0; i < entries; i++) {
		uint8_t hdr[46];
		char name[512];
		uint32_t usize;
		uint16_t fn_len, ex_len, cm_len;
		size_t rlen;

		if (fread(hdr, 1, sizeof(hdr), f) != sizeof(hdr) ||
		    hdr[0] != 'P' || hdr[1] != 'K' || hdr[2] != 1 || hdr[3] != 2)
			break;
		usize = zip_le32(hdr + 24);
		fn_len = zip_le16(hdr + 28);
		ex_len = zip_le16(hdr + 30);
		cm_len = zip_le16(hdr + 32);
		rlen = fn_len < sizeof(name) - 1 ? fn_len : sizeof(name) - 1;
		if (rlen && fread(name, 1, rlen, f) != rlen)
			break;
		name[rlen] = 0;
		if (fseeko(f, (off_t)(fn_len - rlen) + ex_len + cm_len, SEEK_CUR))
			break;
		if (zip_path_unsafe(name)) {
			in->has_traversal = true;
			continue;
		}
		if (strncmp(name, "Payload/", 8))
			continue;
		{
			const char *p = name + 8, *sl = strchr(p, '/');
			size_t dlen = sl ? (size_t)(sl - p) : strlen(p);

			if (dlen <= 4 || dlen >= sizeof(in->bundle_dir) ||
			    memcmp(p + dlen - 4, ".app", 4))
				continue;
			if (!in->bundle_dir[0]) {
				char cand[128];

				memcpy(cand, p, dlen);
				cand[dlen] = 0;
				if (!safe_single_name(cand))
					continue;
				snprintf(in->bundle_dir, sizeof(in->bundle_dir), "%s", cand);
				cand[dlen - 4] = 0;
				snprintf(in->bundle_stem, sizeof(in->bundle_stem), "%s", cand);
			}
			if (strlen(in->bundle_dir) == dlen && !memcmp(p, in->bundle_dir, dlen)) {
				in->unpacked_bytes += usize;
				if (sl && !strcmp(sl + 1, "Info.plist"))
					has_plist = true;
			}
		}
	}
	fclose(f);
	if (in->bundle_dir[0] && has_plist && !in->has_traversal) {
		char apps[PATH_MAX], dst[PATH_MAX];
		struct stat dst_st;

		in->valid = true;
		touchhle_apps_dir(apps, sizeof(apps));
		snprintf(dst, sizeof(dst), "%s/%s", apps, in->bundle_dir);
		in->already_installed = stat(dst, &dst_st) == 0;
	}
}

/* ----------------------------------------------------------- app icons */

struct apps_icon {
	lv_image_dsc_t dsc;
	lv_color_t avg;
};

static struct apps_icon *apps_n72i_load(const char *path)
{
	uint8_t hd[8], *px;
	uint32_t w, h, n, i, r = 0, g = 0, b = 0, a = 0;
	struct apps_icon *ic;
	FILE *f;

	if (!path || !*path || !(f = fopen(path, "rb")))
		return NULL;
	if (fread(hd, 1, 8, f) != 8 || memcmp(hd, "N72I", 4)) {
		fclose(f);
		return NULL;
	}
	w = hd[4] | ((uint32_t)hd[5] << 8);
	h = hd[6] | ((uint32_t)hd[7] << 8);
	n = w * h * 4;
	if (!w || !h || w > 256 || h > 256 || !(px = malloc(n))) {
		fclose(f);
		return NULL;
	}
	if (fread(px, 1, n, f) != n) {
		fclose(f);
		free(px);
		return NULL;
	}
	fclose(f);
	ic = calloc(1, sizeof(*ic));
	if (!ic) {
		free(px);
		return NULL;
	}
	for (i = 0; i < n; i += 4) {
		b += px[i] * px[i + 3];
		g += px[i + 1] * px[i + 3];
		r += px[i + 2] * px[i + 3];
		a += px[i + 3];
	}
	ic->dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
	ic->dsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
	ic->dsc.header.w = w;
	ic->dsc.header.h = h;
	ic->dsc.header.stride = w * 4;
	ic->dsc.data_size = n;
	ic->dsc.data = px;
	ic->avg = a ? lv_color_make(r / a, g / a, b / a) : lv_color_black();
	return ic;
}

static void apps_icon_delete_cb(lv_event_t *e)
{
	struct apps_icon *ic = lv_event_get_user_data(e);

	if (!ic)
		return;
	lv_image_cache_drop(&ic->dsc);
	free((void *)ic->dsc.data);
	free(ic);
}

/* Leading icon box: real .n72i icon if present, otherwise a tonal gamepad badge. */
static lv_obj_t *apps_icon_badge(lv_obj_t *parent, const char *icon_path, int size)
{
	struct apps_icon *ic = apps_n72i_load(icon_path);
	lv_obj_t *box, *im;
	int32_t side;

	if (!ic)
		return m3_badge(parent, N72_SYMBOL_GAMEPAD, M.secondary_c, M.on_secondary_c, size);
	box = lv_obj_create(parent);
	plain(box);
	lv_obj_set_size(box, size, size);
	lv_obj_set_style_bg_color(box, ic->avg, 0);
	lv_obj_set_style_bg_opa(box, LV_OPA_TRANSP, 0);
	lv_obj_set_style_pad_all(box, 0, 0);
	lv_obj_remove_flag(box, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
	im = lv_image_create(box);
	lv_image_set_src(im, &ic->dsc);
	side = LV_MAX(ic->dsc.header.w, ic->dsc.header.h);
	if (side > size)
		lv_image_set_scale(im, 256 * size / side);
	lv_obj_center(im);
	lv_obj_add_event_cb(im, apps_icon_delete_cb, LV_EVENT_DELETE, ic);
	return box;
}

/* --------------------------------------------------------- app scanning */

struct ios_app {
	char stem[128];
	char display_name[80];
	char bundle_id[128];
	char version[32];
	char icon_path[256];
	bool has_app;
	bool has_ipa;
};

static int ios_app_cmp(const void *a, const void *b)
{
	const struct ios_app *x = a, *y = b;

	return strcasecmp(x->display_name, y->display_name);
}

static void ios_app_fill_meta(struct ios_app *a)
{
	char apps[PATH_MAX], path[PATH_MAX], tid[160], line[300];
	FILE *f;

	touchhle_apps_dir(apps, sizeof(apps));
	a->display_name[0] = a->bundle_id[0] = a->version[0] = a->icon_path[0] = 0;
	if (a->has_app) {
		struct app_plist_meta pm;

		snprintf(path, sizeof(path), "%s/%s.app", apps, a->stem);
		plist_read_app_meta(path, &pm);
		if (pm.display_name[0])
			snprintf(a->display_name, sizeof(a->display_name), "%s", pm.display_name);
		else if (pm.bundle_name[0])
			snprintf(a->display_name, sizeof(a->display_name), "%s", pm.bundle_name);
		if (pm.bundle_id[0])
			snprintf(a->bundle_id, sizeof(a->bundle_id), "%s", pm.bundle_id);
		if (pm.short_ver[0])
			snprintf(a->version, sizeof(a->version), "%s", pm.short_ver);
		else if (pm.bundle_ver[0])
			snprintf(a->version, sizeof(a->version), "%s", pm.bundle_ver);
	}
	ios_tile_id(a->stem, tid, sizeof(tid));
	snprintf(path, sizeof(path), IOS_APPS_DIR "/%s.app", tid);
	f = fopen(path, "r");
	if (f) {
		while (fgets(line, sizeof(line), f)) {
			line[strcspn(line, "\r\n")] = 0;
			if (!a->display_name[0] && !strncmp(line, "name=", 5))
				snprintf(a->display_name, sizeof(a->display_name), "%s", line + 5);
			else if (!a->icon_path[0] && !strncmp(line, "image=", 6))
				snprintf(a->icon_path, sizeof(a->icon_path), "%s", line + 6);
		}
		fclose(f);
	}
	if (!a->icon_path[0]) {
		snprintf(path, sizeof(path), IOS_ICONS_DIR "/%s.n72i", tid);
		if (!access(path, R_OK))
			snprintf(a->icon_path, sizeof(a->icon_path), "%s", path);
	}
	if (!a->display_name[0])
		snprintf(a->display_name, sizeof(a->display_name), "%s", a->stem);
}

static struct ios_app *apps_scan(int *out_n)
{
	char apps_dir[PATH_MAX];
	struct ios_app *v = NULL;
	int n = 0, cap = 0;
	struct dirent *de;
	DIR *d;

	*out_n = 0;
	touchhle_apps_dir(apps_dir, sizeof(apps_dir));
	d = opendir(apps_dir);
	if (!d)
		return NULL;
	while ((de = readdir(d))) {
		const char *nm = de->d_name;
		size_t len = strlen(nm);
		bool is_app, is_ipa;
		char stem[128];
		struct stat st;
		int idx = -1;

		if (nm[0] == '.' || len <= 4)
			continue;
		is_app = !strcasecmp(nm + len - 4, ".app");
		is_ipa = !strcasecmp(nm + len - 4, ".ipa");
		if (!is_app && !is_ipa)
			continue;
		if (fstatat(dirfd(d), nm, &st, 0))
			continue;
		if ((is_app && !S_ISDIR(st.st_mode)) || (is_ipa && !S_ISREG(st.st_mode)))
			continue;
		if (len - 4 >= sizeof(stem))
			continue;
		memcpy(stem, nm, len - 4);
		stem[len - 4] = 0;
		if (!safe_single_name(stem))
			continue;
		for (int i = 0; i < n; i++)
			if (!strcmp(v[i].stem, stem)) {
				idx = i;
				break;
			}
		if (idx < 0) {
			if (n == cap) {
				struct ios_app *nv = realloc(v, (cap ? cap * 2 : 16) * sizeof(*nv));

				if (!nv)
					break;
				v = nv;
				cap = cap ? cap * 2 : 16;
			}
			idx = n++;
			memset(&v[idx], 0, sizeof(v[idx]));
			snprintf(v[idx].stem, sizeof(v[idx].stem), "%s", stem);
		}
		if (is_app)
			v[idx].has_app = true;
		if (is_ipa)
			v[idx].has_ipa = true;
	}
	closedir(d);
	for (int i = 0; i < n; i++)
		ios_app_fill_meta(&v[i]);
	if (n > 1)
		qsort(v, n, sizeof(*v), ios_app_cmp);
	*out_n = n;
	return v;
}

static const char *ios_app_kind(const struct ios_app *a)
{
	if (a->has_app && a->has_ipa)
		return "App + IPA";
	if (a->has_app)
		return "App bundle";
	return "IPA archive";
}

static void apps_summary(char *buf, size_t len)
{
	int n = 0;
	struct ios_app *v = apps_scan(&n);

	free(v);
	if (n == 0)
		snprintf(buf, len, "No iOS apps installed");
	else if (n == 1)
		snprintf(buf, len, "1 iOS app installed");
	else
		snprintf(buf, len, "%d iOS apps installed", n);
}

/* ------------------------------------------- Settings > App manager UI */

static lv_obj_t *set_apps_sub;
static lv_obj_t *apps_page;
static lv_obj_t *apps_list_box;
static lv_obj_t *apps_refresh_sub;
static bool apps_refreshing;
static bool apps_op_busy;

struct apps_row_ref {
	char stem[128];
	char kind[24];
	lv_obj_t *sub;
};

struct apps_list_state {
	struct apps_row_ref *rows;
	int n;
};

static struct apps_list_state *apps_lstate;

static void apps_summary_sync(void)
{
	if (set_apps_sub && lv_obj_is_valid(set_apps_sub)) {
		char sub[48];

		apps_summary(sub, sizeof(sub));
		label_set_if_changed(set_apps_sub, sub);
	}
}

static void apps_list_populate(void);
static void open_app_detail(lv_event_t *e);
static char app_detail_stem[128];

static void apps_refresh_done(const char *out, void *ud)
{
	int st = out && *out ? atoi(out) : -1;

	LV_UNUSED(ud);
	apps_refreshing = false;
	if (st == 10)
		apps_reload();
	if (apps_refresh_sub)
		label_set_if_changed(apps_refresh_sub, st == 10 ? "Updated" :
				     st == 0 ? "Up to date" : "Could not look");
	apps_summary_sync();
	if (apps_page && lv_obj_is_valid(apps_page))
		apps_list_populate();
}

static void apps_refresh_cb(lv_event_t *e)
{
	LV_UNUSED(e);
	if (apps_refreshing || apps_op_busy)
		return;
	apps_refreshing = true;
	if (apps_refresh_sub)
		label_set_if_changed(apps_refresh_sub, "Looking for apps...");
	job_run(IOS_TILES " >/dev/null 2>&1; echo $?", NULL, apps_refresh_done, NULL);
}

static void apps_open_files_cb(lv_event_t *e)
{
	LV_UNUSED(e);
	files_open_dir(FILES_ROOT);
}

static void apps_row_cb(lv_event_t *e)
{
	const char *stem = lv_event_get_user_data(e);

	if (!stem || !*stem)
		return;
	snprintf(app_detail_stem, sizeof(app_detail_stem), "%s", stem);
	open_app_detail(NULL);
}

static void apps_lstate_delete_cb(lv_event_t *e)
{
	struct apps_list_state *ls = lv_event_get_user_data(e);

	if (!ls)
		return;
	if (apps_lstate == ls)
		apps_lstate = NULL;
	free(ls->rows);
	free(ls);
}

static void apps_sizes_done(const char *out, void *ud)
{
	struct apps_list_state *ls = ud;
	uint64_t *kb;
	const char *p;

	if (!ls || ls != apps_lstate || !apps_page || !lv_obj_is_valid(apps_page))
		return;
	kb = calloc((size_t)(ls->n ? ls->n : 1), sizeof(*kb));
	if (!kb)
		return;
	for (p = out; p && *p; ) {
		unsigned long long sz = 0;
		char path[PATH_MAX];
		const char *nl = strchr(p, '\n');

		if (sscanf(p, "%llu %4095[^\n]", &sz, path) == 2) {
			const char *base = strrchr(path, '/');
			size_t blen;

			base = base ? base + 1 : path;
			blen = strlen(base);
			if (blen > 4 && (!strcasecmp(base + blen - 4, ".app") ||
					 !strcasecmp(base + blen - 4, ".ipa"))) {
				for (int i = 0; i < ls->n; i++)
					if (strlen(ls->rows[i].stem) == blen - 4 &&
					    !memcmp(ls->rows[i].stem, base, blen - 4)) {
						kb[i] += sz;
						break;
					}
			}
		}
		p = nl ? nl + 1 : NULL;
	}
	for (int i = 0; i < ls->n; i++) {
		char szs[32], line[64];

		if (!ls->rows[i].sub || !lv_obj_is_valid(ls->rows[i].sub) || !kb[i])
			continue;
		storage_fmt(szs, sizeof(szs), kb[i] * 1024ULL, "");
		snprintf(line, sizeof(line), "%s, %s", ls->rows[i].kind, szs);
		label_set_if_changed(ls->rows[i].sub, line);
	}
	free(kb);
}

static void apps_list_populate(void)
{
	struct ios_app *v;
	int n = 0, i;
	lv_obj_t *c, *row;

	if (!apps_list_box || !lv_obj_is_valid(apps_list_box))
		return;
	apps_lstate = NULL;
	lv_obj_clean(apps_list_box);
	v = apps_scan(&n);
	if (!n) {
		c = m3_card(apps_list_box, M.surface_c);
		lv_obj_set_height(c, LV_SIZE_CONTENT);
		lv_obj_set_flex_flow(c, LV_FLEX_FLOW_COLUMN);
		lv_obj_set_flex_align(c, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
				      LV_FLEX_ALIGN_CENTER);
		lv_obj_set_style_pad_ver(c, 24, 0);
		lv_obj_set_style_pad_row(c, 8, 0);
		m3_badge(c, N72_SYMBOL_GAMEPAD, M.surface_c_highest, M.on_surface_v, 56);
		m3_label(c, "No iOS apps installed", &lv_font_montserrat_16, M.on_surface);
		row = m3_label(c, "Copy .ipa files to the iPod and open them in Files to install.",
			       &lv_font_montserrat_14, M.on_surface_v);
		lv_obj_set_width(row, lv_pct(100));
		lv_label_set_long_mode(row, LV_LABEL_LONG_WRAP);
		lv_obj_set_style_text_align(row, LV_TEXT_ALIGN_CENTER, 0);
		free(v);
		return;
	}
	apps_lstate = calloc(1, sizeof(*apps_lstate));
	if (!apps_lstate || !(apps_lstate->rows = calloc((size_t)n, sizeof(*apps_lstate->rows)))) {
		free(apps_lstate);
		apps_lstate = NULL;
		free(v);
		return;
	}
	apps_lstate->n = n;
	c = m3_card(apps_list_box, M.surface_c);
	lv_obj_add_event_cb(c, apps_lstate_delete_cb, LV_EVENT_DELETE, apps_lstate);
	lv_obj_set_style_pad_all(c, 4, 0);
	lv_obj_set_flex_flow(c, LV_FLEX_FLOW_COLUMN);
	for (i = 0; i < n; i++) {
		lv_obj_t *sub = NULL, *r, *icon_box;

		snprintf(apps_lstate->rows[i].stem, sizeof(apps_lstate->rows[i].stem),
			 "%s", v[i].stem);
		snprintf(apps_lstate->rows[i].kind, sizeof(apps_lstate->rows[i].kind),
			 "%s", ios_app_kind(&v[i]));
		r = m3_row_ex(c, NULL, M.secondary_c, M.on_secondary_c,
			      v[i].display_name, apps_lstate->rows[i].kind,
			      apps_row_cb, apps_lstate->rows[i].stem, &sub, true);
		icon_box = apps_icon_badge(r, v[i].icon_path, 40);
		lv_obj_move_to_index(icon_box, 0);
		apps_lstate->rows[i].sub = sub;
	}
	free(v);
	{
		char apps_dir[PATH_MAX], q[PATH_MAX * 2 + 16], cmd[PATH_MAX * 2 + 64];

		touchhle_apps_dir(apps_dir, sizeof(apps_dir));
		shq(apps_dir, q, sizeof(q));
		snprintf(cmd, sizeof(cmd), "du -sk %s/*.app %s/*.ipa 2>/dev/null", q, q);
		job_run(cmd, apps_page, apps_sizes_done, apps_lstate);
	}
}

void open_apps(lv_event_t *e)
{
	nav_mark(open_apps, NULL);
	lv_obj_t *scr, *body, *c;

	LV_UNUSED(e);
	body = m3_page("App manager", &scr);
	apps_page = scr;
	obj_track(&apps_page);

	c = m3_card(body, M.surface_c);
	lv_obj_set_style_pad_all(c, 4, 0);
	lv_obj_set_flex_flow(c, LV_FLEX_FLOW_COLUMN);
	if (!access(IOS_TILES, X_OK)) {
		m3_row_ex(c, LV_SYMBOL_REFRESH, M.secondary_c, M.on_secondary_c,
			  "Refresh app list", apps_refreshing ? "Looking for apps..." :
			  "Find iOS apps added or removed", apps_refresh_cb, NULL,
			  &apps_refresh_sub, false);
		obj_track(&apps_refresh_sub);
	}
	m3_row(c, LV_SYMBOL_DOWNLOAD, "Install from Files", "Open an .ipa file to install",
	       apps_open_files_cb, NULL, NULL);

	m3_section(body, "Installed apps");
	apps_list_box = lv_obj_create(body);
	obj_track(&apps_list_box);
	lv_obj_remove_style_all(apps_list_box);
	lv_obj_set_size(apps_list_box, lv_pct(100), LV_SIZE_CONTENT);
	lv_obj_set_flex_flow(apps_list_box, LV_FLEX_FLOW_COLUMN);
	lv_obj_set_style_pad_row(apps_list_box, 12, 0);
	lv_obj_remove_flag(apps_list_box, LV_OBJ_FLAG_SCROLLABLE);

	apps_list_populate();
	push(scr);
}

/* ------------------------------------------- App manager > App detail */

static lv_obj_t *ad_page;
static lv_obj_t *ad_card;
static lv_obj_t *ad_size_sub;
static lv_obj_t *ad_data_sub;
static lv_obj_t *ad_log_sub;
static lv_obj_t *ad_status;
static lv_obj_t *ad_rm_ipa_sub;
static lv_obj_t *ad_clear_data_sub;
static lv_obj_t *ad_uninst_sub;
static int ad_confirm;		/* 0 none, 1 rm ipa, 2 clear data, 3 uninstall */
static struct ios_app ad_app;

static bool app_detail_load(const char *stem, struct ios_app *a)
{
	char apps[PATH_MAX], p[PATH_MAX];
	struct stat st;

	memset(a, 0, sizeof(*a));
	if (!safe_single_name(stem))
		return false;
	snprintf(a->stem, sizeof(a->stem), "%s", stem);
	touchhle_apps_dir(apps, sizeof(apps));
	snprintf(p, sizeof(p), "%s/%s.app", apps, stem);
	a->has_app = !stat(p, &st) && S_ISDIR(st.st_mode);
	snprintf(p, sizeof(p), "%s/%s.ipa", apps, stem);
	a->has_ipa = !stat(p, &st) && S_ISREG(st.st_mode);
	if (!a->has_app && !a->has_ipa)
		return false;
	ios_app_fill_meta(a);
	return true;
}

static bool app_has_sandbox(const struct ios_app *a, char *out, size_t len)
{
	char sb[PATH_MAX];
	struct stat st;

	if (!safe_bundle_id(a->bundle_id))
		return false;
	touchhle_sandbox_dir(sb, sizeof(sb));
	snprintf(out, len, "%s/%s", sb, a->bundle_id);
	return !stat(out, &st) && S_ISDIR(st.st_mode);
}

static bool app_has_log(const struct ios_app *a, char *out, size_t len)
{
	struct stat st;

	snprintf(out, len, "%s/%s.log", touchhle_dir(), a->stem);
	return !stat(out, &st) && S_ISREG(st.st_mode);
}

static void ad_set_status(const char *msg)
{
	if (ad_status && lv_obj_is_valid(ad_status))
		label_set_if_changed(ad_status, msg);
}

static void ad_sizes_done(const char *out, void *ud)
{
	unsigned long long app_kb = 0, data_kb = 0, log_kb = 0;
	const char *p;
	char s1[32], line[192];

	LV_UNUSED(ud);
	if (!ad_page || !lv_obj_is_valid(ad_page))
		return;
	for (p = out; p && *p; ) {
		unsigned long long k = 0;
		char tag[16];
		const char *nl = strchr(p, '\n');

		if (sscanf(p, "%15s %llu", tag, &k) == 2) {
			if (!strcmp(tag, "APP"))
				app_kb += k;
			else if (!strcmp(tag, "DATA"))
				data_kb += k;
			else if (!strcmp(tag, "LOG"))
				log_kb += k;
		}
		p = nl ? nl + 1 : NULL;
	}
	if (ad_size_sub && lv_obj_is_valid(ad_size_sub)) {
		if (app_kb) {
			storage_fmt(s1, sizeof(s1), app_kb * 1024ULL, "");
			if (ad_app.has_app && ad_app.has_ipa)
				snprintf(line, sizeof(line), "%s (%s.app + .ipa)", s1, ad_app.stem);
			else
				snprintf(line, sizeof(line), "%s (%s.%s)", s1, ad_app.stem,
					 ad_app.has_app ? "app" : "ipa");
			label_set_if_changed(ad_size_sub, line);
		} else {
			label_set_if_changed(ad_size_sub, ios_app_kind(&ad_app));
		}
	}
	if (ad_data_sub && lv_obj_is_valid(ad_data_sub)) {
		if (data_kb) {
			storage_fmt(s1, sizeof(s1), data_kb * 1024ULL, "");
			label_set_if_changed(ad_data_sub, s1);
		} else if (safe_bundle_id(ad_app.bundle_id)) {
			label_set_if_changed(ad_data_sub, "No saved data");
		}
	}
	if (ad_log_sub && lv_obj_is_valid(ad_log_sub) && log_kb) {
		storage_fmt(s1, sizeof(s1), log_kb * 1024ULL, "");
		label_set_if_changed(ad_log_sub, s1);
	}
}

static void ad_rebuild_in_place(void)
{
	if (!ad_page || !lv_obj_is_valid(ad_page) || lv_screen_active() != ad_page)
		return;
	if (!app_detail_load(app_detail_stem, &ad_app)) {
		go_back();
		return;
	}
	/* Replace current detail page cleanly on top of the nav stack. */
	if (nav_n > 0 && nav[nav_n - 1] == ad_page) {
		lv_obj_t *old = ad_page;

		nav_n--;
		push_quiet = true;
		open_app_detail(NULL);
		push_quiet = false;
		if (push_quiet_scr) {
			lv_screen_load(push_quiet_scr);
			push_quiet_scr = NULL;
			lv_obj_delete_async(old);
		}
	}
}

static void ad_launch_cb(lv_event_t *e)
{
	char apps[PATH_MAX], path[PATH_MAX], q[PATH_MAX * 2 + 16], cmd[PATH_MAX * 2 + 64];

	LV_UNUSED(e);
	if (apps_op_busy)
		return;
	if (ui_rot && !ui_turn(0))
		return;
	touchhle_apps_dir(apps, sizeof(apps));
	snprintf(path, sizeof(path), "%s/%s.%s", apps, ad_app.stem,
		 ad_app.has_app ? "app" : "ipa");
	shq(path, q, sizeof(q));
	snprintf(cmd, sizeof(cmd), TOUCHHLE_CMD " %s", q);
	if (ad_card && lv_obj_is_valid(ad_card))
		app_launch(cmd, ad_card);
}

static void ad_action_done(const char *out, void *ud)
{
	int what = (int)(intptr_t)ud;
	bool ok = out && strstr(out, "app-ok") != NULL;

	apps_op_busy = false;
	ad_confirm = 0;
	if (ok) {
		if (what == 1 || what == 3)
			apps_reload();
		apps_summary_sync();
		if (apps_page && lv_obj_is_valid(apps_page))
			apps_list_populate();
		if (what == 3) {
			if (ad_page && lv_obj_is_valid(ad_page) && lv_screen_active() == ad_page)
				go_back();
			return;
		}
		ad_rebuild_in_place();
	} else {
		const char *err = out ? strstr(out, "app-err ") : NULL;

		if (err) {
			char msg[160];
			size_t n = strcspn(err + 8, "\r\n");

			snprintf(msg, sizeof(msg), "%.*s", (int)LV_MIN(n, sizeof(msg) - 1), err + 8);
			ad_set_status(msg);
		} else {
			ad_set_status("Action failed");
		}
	}
}

/* Extract a bare .ipa inside touchHLE_apps/ into a .app bundle and remove the .ipa. */
static void ad_extract_cb(lv_event_t *e)
{
	char apps[PATH_MAX], ipa[PATH_MAX], qa[PATH_MAX * 2 + 16], qs[PATH_MAX * 2 + 16];
	char qbd[300], cmd[PATH_MAX * 4 + 512];
	struct ipa_info info;
	struct statvfs v;

	LV_UNUSED(e);
	if (apps_op_busy || !ad_app.has_ipa || ad_app.has_app)
		return;
	touchhle_apps_dir(apps, sizeof(apps));
	snprintf(ipa, sizeof(ipa), "%s/%s.ipa", apps, ad_app.stem);
	ipa_inspect(ipa, &info);
	if (!info.valid) {
		ad_set_status("Not a valid iOS .ipa archive");
		return;
	}
	if (!statvfs(touchhle_dir(), &v) &&
	    (uint64_t)v.f_bavail * v.f_frsize < info.unpacked_bytes + (4ULL << 20)) {
		ad_set_status("Not enough free space to unpack this IPA");
		return;
	}
	shq(apps, qa, sizeof(qa));
	shq(ipa, qs, sizeof(qs));
	shq(info.bundle_dir, qbd, sizeof(qbd));
	snprintf(cmd, sizeof(cmd),
		 "APPS=%s; SRC=%s; BDIR=%s; "
		 "TMP=\"$APPS/.ipa-install.$$\"; rm -rf \"$TMP\"; mkdir -p \"$TMP\" || { echo 'app-err Cannot create temp folder'; exit 1; }; "
		 "if ! unzip -oq \"$SRC\" -d \"$TMP\" >/dev/null 2>&1; then rm -rf \"$TMP\"; echo 'app-err Could not unpack IPA'; exit 1; fi; "
		 "if [ ! -f \"$TMP/Payload/$BDIR/Info.plist\" ]; then rm -rf \"$TMP\"; echo 'app-err App bundle missing in IPA'; exit 1; fi; "
		 "DST=\"$APPS/$BDIR\"; "
		 "if [ -e \"$DST\" ]; then mv \"$DST\" \"$TMP/.old.app\" || { rm -rf \"$TMP\"; echo 'app-err Could not replace old app'; exit 1; }; fi; "
		 "if ! mv \"$TMP/Payload/$BDIR\" \"$DST\"; then [ -e \"$TMP/.old.app\" ] && mv \"$TMP/.old.app\" \"$DST\"; rm -rf \"$TMP\"; echo 'app-err Could not move app into place'; exit 1; fi; "
		 "rm -rf \"$TMP\" \"$SRC\"; "
		 "[ -x " IOS_TILES " ] && " IOS_TILES " >/dev/null 2>&1; "
		 "echo app-ok",
		 qa, qs, qbd);
	apps_op_busy = true;
	snprintf(app_detail_stem, sizeof(app_detail_stem), "%s", info.bundle_stem);
	ad_set_status("Unpacking IPA... This may take a moment.");
	job_run(cmd, NULL, ad_action_done, (void *)(intptr_t)1);
}

static void ad_rm_ipa_cb(lv_event_t *e)
{
	char apps[PATH_MAX], ipa[PATH_MAX], q[PATH_MAX * 2 + 16], cmd[PATH_MAX * 2 + 64];

	LV_UNUSED(e);
	if (apps_op_busy || !ad_app.has_ipa || !ad_app.has_app)
		return;
	if (ad_confirm != 1) {
		ad_confirm = 1;
		if (ad_rm_ipa_sub)
			label_set_if_changed(ad_rm_ipa_sub, "Tap again to delete the .ipa file");
		return;
	}
	touchhle_apps_dir(apps, sizeof(apps));
	snprintf(ipa, sizeof(ipa), "%s/%s.ipa", apps, ad_app.stem);
	shq(ipa, q, sizeof(q));
	snprintf(cmd, sizeof(cmd), "rm -f %s && echo app-ok || echo 'app-err Could not remove .ipa'", q);
	apps_op_busy = true;
	ad_set_status("Removing leftover .ipa...");
	job_run(cmd, NULL, ad_action_done, (void *)(intptr_t)2);
}

static void ad_clear_data_cb(lv_event_t *e)
{
	char sb[PATH_MAX], q[PATH_MAX * 2 + 16], cmd[PATH_MAX * 2 + 64];

	LV_UNUSED(e);
	if (apps_op_busy || !app_has_sandbox(&ad_app, sb, sizeof(sb)))
		return;
	if (ad_confirm != 2) {
		ad_confirm = 2;
		if (ad_clear_data_sub)
			label_set_if_changed(ad_clear_data_sub, "Tap again to erase all saves");
		return;
	}
	shq(sb, q, sizeof(q));
	snprintf(cmd, sizeof(cmd), "rm -rf %s && echo app-ok || echo 'app-err Could not clear data'", q);
	apps_op_busy = true;
	ad_set_status("Clearing saved data...");
	job_run(cmd, NULL, ad_action_done, (void *)(intptr_t)2);
}

static void ad_clear_log_cb(lv_event_t *e)
{
	char logp[PATH_MAX], q[PATH_MAX * 2 + 16], cmd[PATH_MAX * 2 + 64];

	LV_UNUSED(e);
	if (apps_op_busy || !app_has_log(&ad_app, logp, sizeof(logp)))
		return;
	shq(logp, q, sizeof(q));
	snprintf(cmd, sizeof(cmd), "rm -f %s && echo app-ok || echo 'app-err Could not remove log'", q);
	apps_op_busy = true;
	ad_set_status("Removing log...");
	job_run(cmd, NULL, ad_action_done, (void *)(intptr_t)2);
}

static void ad_uninstall_cb(lv_event_t *e)
{
	char apps[PATH_MAX], p_app[PATH_MAX], p_ipa[PATH_MAX], p_sb[PATH_MAX], p_log[PATH_MAX];
	char qa[PATH_MAX * 2 + 16], qi[PATH_MAX * 2 + 16], qs[PATH_MAX * 2 + 16], ql[PATH_MAX * 2 + 16];
	char cmd[PATH_MAX * 4 + 256];
	size_t o = 0;

	LV_UNUSED(e);
	if (apps_op_busy || !safe_single_name(ad_app.stem))
		return;
	if (ad_confirm != 3) {
		ad_confirm = 3;
		if (ad_uninst_sub)
			label_set_if_changed(ad_uninst_sub, "Tap again to uninstall permanently");
		return;
	}
	touchhle_apps_dir(apps, sizeof(apps));
	snprintf(p_app, sizeof(p_app), "%s/%s.app", apps, ad_app.stem);
	snprintf(p_ipa, sizeof(p_ipa), "%s/%s.ipa", apps, ad_app.stem);
	shq(p_app, qa, sizeof(qa));
	shq(p_ipa, qi, sizeof(qi));
	o += (size_t)snprintf(cmd + o, sizeof(cmd) - o, "rm -rf %s %s", qa, qi);
	if (app_has_sandbox(&ad_app, p_sb, sizeof(p_sb))) {
		shq(p_sb, qs, sizeof(qs));
		o += (size_t)snprintf(cmd + o, sizeof(cmd) - o, " %s", qs);
	}
	if (app_has_log(&ad_app, p_log, sizeof(p_log))) {
		shq(p_log, ql, sizeof(ql));
		o += (size_t)snprintf(cmd + o, sizeof(cmd) - o, " %s", ql);
	}
	snprintf(cmd + o, sizeof(cmd) - o,
		 " && { [ -x " IOS_TILES " ] && " IOS_TILES " >/dev/null 2>&1; true; } && echo app-ok "
		 "|| echo 'app-err Could not uninstall app'");
	apps_op_busy = true;
	ad_set_status("Uninstalling...");
	job_run(cmd, NULL, ad_action_done, (void *)(intptr_t)3);
}

static void open_app_detail(lv_event_t *e)
{
	lv_obj_t *scr, *body, *c, *col, *b, *row, *icon_box;
	char sub[128], sb[PATH_MAX], logp[PATH_MAX];
	bool has_sb, has_log;

	LV_UNUSED(e);
	if (!app_detail_load(app_detail_stem, &ad_app))
		return;
	nav_mark(open_app_detail, NULL);
	ad_confirm = 0;

	body = m3_page("App info", &scr);
	ad_page = scr;
	obj_track(&ad_page);

	/* Header card: app icon (used as launch zoom origin), name, version, bundle ID */
	c = ad_card = m3_card(body, M.surface_c);
	obj_track(&ad_card);
	lv_obj_set_height(c, LV_SIZE_CONTENT);
	lv_obj_set_flex_flow(c, LV_FLEX_FLOW_ROW);
	lv_obj_set_flex_align(c, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
	lv_obj_set_style_pad_column(c, 16, 0);
	icon_box = apps_icon_badge(c, ad_app.icon_path, 56);
	LV_UNUSED(icon_box);
	col = lv_obj_create(c);
	plain(col);
	lv_obj_set_style_bg_opa(col, LV_OPA_TRANSP, 0);
	lv_obj_set_style_pad_all(col, 0, 0);
	lv_obj_set_height(col, LV_SIZE_CONTENT);
	lv_obj_set_flex_grow(col, 1);
	lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
	lv_obj_set_style_pad_row(col, 2, 0);
	lv_obj_remove_flag(col, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
	b = m3_label(col, ad_app.display_name, &lv_font_montserrat_20, M.on_surface);
	lv_label_set_long_mode(b, LV_LABEL_LONG_DOT);
	lv_obj_set_width(b, lv_pct(100));
	if (ad_app.version[0])
		snprintf(sub, sizeof(sub), "Version %s, %s", ad_app.version, ios_app_kind(&ad_app));
	else
		snprintf(sub, sizeof(sub), "%s", ios_app_kind(&ad_app));
	b = m3_label(col, sub, &lv_font_montserrat_14, M.on_surface_v);
	lv_label_set_long_mode(b, LV_LABEL_LONG_DOT);
	lv_obj_set_width(b, lv_pct(100));
	if (ad_app.bundle_id[0]) {
		b = m3_label(col, ad_app.bundle_id, &lv_font_montserrat_12, M.on_surface_v);
		lv_label_set_long_mode(b, LV_LABEL_LONG_DOT);
		lv_obj_set_width(b, lv_pct(100));
	}

	/* Launch button */
	if (have_tool(TOUCHHLE_CMD)) {
		row = lv_obj_create(body);
		lv_obj_remove_style_all(row);
		lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
		lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
		lv_obj_set_style_pad_column(row, 12, 0);
		m3_button(row, "Launch", true, ad_launch_cb, NULL);
	}

	/* Storage info */
	has_sb = app_has_sandbox(&ad_app, sb, sizeof(sb));
	has_log = app_has_log(&ad_app, logp, sizeof(logp));
	m3_section(body, "Storage");
	c = m3_card(body, M.surface_c);
	lv_obj_set_style_pad_all(c, 4, 0);
	lv_obj_set_flex_flow(c, LV_FLEX_FLOW_COLUMN);
	m3_row_ex(c, LV_SYMBOL_SD_CARD, M.primary_c, M.on_primary_c,
		  "App size", "Calculating...", NULL, NULL, &ad_size_sub, false);
	obj_track(&ad_size_sub);
	m3_row_ex(c, LV_SYMBOL_DIRECTORY, M.secondary_c, M.on_secondary_c,
		  "Saved data", has_sb ? "Calculating..." :
		  ad_app.bundle_id[0] ? "No saved data" : "Unpack IPA to view",
		  NULL, NULL, &ad_data_sub, false);
	obj_track(&ad_data_sub);
	ad_log_sub = NULL;
	if (has_log) {
		m3_row_ex(c, LV_SYMBOL_FILE, M.secondary_c, M.on_secondary_c,
			  "Log file", "Calculating...", NULL, NULL, &ad_log_sub, false);
		obj_track(&ad_log_sub);
	}

	/* Management actions */
	m3_section(body, "Manage");
	c = m3_card(body, M.surface_c);
	lv_obj_set_style_pad_all(c, 4, 0);
	lv_obj_set_flex_flow(c, LV_FLEX_FLOW_COLUMN);
	ad_rm_ipa_sub = ad_clear_data_sub = ad_uninst_sub = NULL;
	if (ad_app.has_ipa && !ad_app.has_app) {
		m3_row_ex(c, LV_SYMBOL_DOWNLOAD, M.tertiary_c, M.on_tertiary_c,
			  "Extract to .app", "Unpack for lower memory use",
			  ad_extract_cb, NULL, NULL, false);
	}
	if (ad_app.has_app && ad_app.has_ipa) {
		m3_row_ex(c, LV_SYMBOL_TRASH, M.secondary_c, M.on_secondary_c,
			  "Remove leftover .ipa", "Free space, keep installed app",
			  ad_rm_ipa_cb, NULL, &ad_rm_ipa_sub, false);
		obj_track(&ad_rm_ipa_sub);
	}
	if (has_sb) {
		m3_row_ex(c, LV_SYMBOL_CLOSE, M.secondary_c, M.on_secondary_c,
			  "Clear app data", "Delete saves and preferences",
			  ad_clear_data_cb, NULL, &ad_clear_data_sub, false);
		obj_track(&ad_clear_data_sub);
	}
	if (has_log) {
		m3_row_ex(c, LV_SYMBOL_FILE, M.secondary_c, M.on_secondary_c,
			  "Clear log", "Delete touchHLE log file",
			  ad_clear_log_cb, NULL, NULL, false);
	}
	m3_row_ex(c, LV_SYMBOL_TRASH, M.error, lv_color_white(),
		  "Uninstall", "Remove app, tile, and saved data",
		  ad_uninstall_cb, NULL, &ad_uninst_sub, false);
	obj_track(&ad_uninst_sub);

	ad_status = m3_label(body, "", &lv_font_montserrat_14, M.on_surface_v);
	lv_obj_set_width(ad_status, lv_pct(100));
	lv_label_set_long_mode(ad_status, LV_LABEL_LONG_WRAP);
	lv_obj_set_style_pad_hor(ad_status, 8, 0);
	obj_track(&ad_status);

	push(scr);

	/* Compute sizes asynchronously */
	{
		char apps[PATH_MAX], p1[PATH_MAX], p2[PATH_MAX];
		char q1[PATH_MAX * 2 + 16], q2[PATH_MAX * 2 + 16];
		char cmd[PATH_MAX * 4 + 256];
		size_t o = 0;

		touchhle_apps_dir(apps, sizeof(apps));
		if (ad_app.has_app) {
			snprintf(p1, sizeof(p1), "%s/%s.app", apps, ad_app.stem);
			shq(p1, q1, sizeof(q1));
			o += (size_t)snprintf(cmd + o, sizeof(cmd) - o,
					      "k=$(du -sk %s 2>/dev/null | cut -f1); [ -n \"$k\" ] && echo \"APP $k\"; ",
					      q1);
		}
		if (ad_app.has_ipa) {
			snprintf(p2, sizeof(p2), "%s/%s.ipa", apps, ad_app.stem);
			shq(p2, q2, sizeof(q2));
			o += (size_t)snprintf(cmd + o, sizeof(cmd) - o,
					      "k=$(du -sk %s 2>/dev/null | cut -f1); [ -n \"$k\" ] && echo \"APP $k\"; ",
					      q2);
		}
		if (has_sb) {
			shq(sb, q1, sizeof(q1));
			o += (size_t)snprintf(cmd + o, sizeof(cmd) - o,
					      "k=$(du -sk %s 2>/dev/null | cut -f1); [ -n \"$k\" ] && echo \"DATA $k\"; ",
					      q1);
		}
		if (has_log) {
			shq(logp, q1, sizeof(q1));
			snprintf(cmd + o, sizeof(cmd) - o,
				 "k=$(du -sk %s 2>/dev/null | cut -f1); [ -n \"$k\" ] && echo \"LOG $k\"",
				 q1);
		}
		if (cmd[0])
			job_run(cmd, scr, ad_sizes_done, NULL);
	}
}

/* ------------------------------------------- Files > Install .ipa page */

static char ipa_src_path[PATH_MAX];
static struct ipa_info ipa_cur;
static bool ipa_del_after;
static bool ipa_installing;
static bool ipa_done_ok;
static char ipa_installed_path[PATH_MAX];
static lv_obj_t *ipa_page;
static lv_obj_t *ipa_card;
static lv_obj_t *ipa_status_lbl;
static lv_obj_t *ipa_btn_row;

static void ipa_del_sw_cb(lv_event_t *e)
{
	ipa_del_after = lv_obj_has_state(lv_event_get_target(e), LV_STATE_CHECKED);
}

static void ipa_launch_cb(lv_event_t *e)
{
	char q[PATH_MAX * 2 + 16], cmd[PATH_MAX * 2 + 64];

	LV_UNUSED(e);
	if (!ipa_installed_path[0])
		return;
	if (ui_rot && !ui_turn(0))
		return;
	shq(ipa_installed_path, q, sizeof(q));
	snprintf(cmd, sizeof(cmd), TOUCHHLE_CMD " %s", q);
	if (ipa_card && lv_obj_is_valid(ipa_card))
		app_launch(cmd, ipa_card);
}

static void ipa_open_mgr_cb(lv_event_t *e)
{
	LV_UNUSED(e);
	open_apps(NULL);
}

static void ipa_rebuild_btns(void);

static void ipa_install_done(const char *out, void *ud)
{
	bool ok = out && strstr(out, "ipa-ok") != NULL;

	LV_UNUSED(ud);
	ipa_installing = false;
	if (ok) {
		ipa_done_ok = true;
		apps_reload();
		apps_summary_sync();
		if (apps_page && lv_obj_is_valid(apps_page))
			apps_list_populate();
		if (ipa_status_lbl && lv_obj_is_valid(ipa_status_lbl))
			label_set_if_changed(ipa_status_lbl,
					     "Installed! Added to Home screen.");
		ipa_rebuild_btns();
	} else {
		const char *err = out ? strstr(out, "ipa-err ") : NULL;
		char msg[180];

		if (err) {
			size_t n = strcspn(err + 8, "\r\n");

			snprintf(msg, sizeof(msg), "Install failed: %.*s",
				 (int)LV_MIN(n, 140), err + 8);
		} else {
			snprintf(msg, sizeof(msg), "Install failed");
		}
		if (ipa_status_lbl && lv_obj_is_valid(ipa_status_lbl))
			label_set_if_changed(ipa_status_lbl, msg);
		ipa_rebuild_btns();
	}
}

static void ipa_install_cb(lv_event_t *e)
{
	char apps[PATH_MAX], qa[PATH_MAX * 2 + 16], qs[PATH_MAX * 2 + 16];
	char qbd[300], cmd[PATH_MAX * 4 + 600];

	LV_UNUSED(e);
	if (ipa_installing || !ipa_cur.valid)
		return;
	touchhle_apps_dir(apps, sizeof(apps));
	snprintf(ipa_installed_path, sizeof(ipa_installed_path), "%s/%s",
		 apps, ipa_cur.bundle_dir);
	shq(apps, qa, sizeof(qa));
	shq(ipa_src_path, qs, sizeof(qs));
	shq(ipa_cur.bundle_dir, qbd, sizeof(qbd));
	snprintf(cmd, sizeof(cmd),
		 "APPS=%s; SRC=%s; BDIR=%s; "
		 "mkdir -p \"$APPS\" || { echo 'ipa-err Cannot create touchHLE_apps folder'; exit 1; }; "
		 "TMP=\"$APPS/.ipa-install.$$\"; rm -rf \"$TMP\"; mkdir -p \"$TMP\" || { echo 'ipa-err Cannot create temp folder'; exit 1; }; "
		 "if ! unzip -oq \"$SRC\" -d \"$TMP\" >/dev/null 2>&1; then rm -rf \"$TMP\"; echo 'ipa-err Could not unpack archive'; exit 1; fi; "
		 "if [ ! -f \"$TMP/Payload/$BDIR/Info.plist\" ]; then rm -rf \"$TMP\"; echo 'ipa-err App bundle not found in archive'; exit 1; fi; "
		 "DST=\"$APPS/$BDIR\"; "
		 "if [ -e \"$DST\" ]; then mv \"$DST\" \"$TMP/.old.app\" || { rm -rf \"$TMP\"; echo 'ipa-err Could not replace existing app'; exit 1; }; fi; "
		 "if ! mv \"$TMP/Payload/$BDIR\" \"$DST\"; then [ -e \"$TMP/.old.app\" ] && mv \"$TMP/.old.app\" \"$DST\"; rm -rf \"$TMP\"; echo 'ipa-err Could not move app into touchHLE'; exit 1; fi; "
		 "rm -rf \"$TMP\"; %s"
		 "[ -x " IOS_TILES " ] && " IOS_TILES " >/dev/null 2>&1; "
		 "echo ipa-ok",
		 qa, qs, qbd, ipa_del_after ? "rm -f \"$SRC\"; " : "");
	ipa_installing = true;
	ipa_done_ok = false;
	if (ipa_status_lbl && lv_obj_is_valid(ipa_status_lbl))
		label_set_if_changed(ipa_status_lbl, "Installing to touchHLE... This may take a moment.");
	ipa_rebuild_btns();
	job_run(cmd, NULL, ipa_install_done, NULL);
}

static void ipa_rebuild_btns(void)
{
	if (!ipa_btn_row || !lv_obj_is_valid(ipa_btn_row))
		return;
	lv_obj_clean(ipa_btn_row);
	if (ipa_installing)
		return;
	if (ipa_done_ok) {
		if (have_tool(TOUCHHLE_CMD))
			m3_button(ipa_btn_row, "Launch", true, ipa_launch_cb, NULL);
		m3_button(ipa_btn_row, "App manager", false, ipa_open_mgr_cb, NULL);
		return;
	}
	if (ipa_cur.valid) {
		struct statvfs v;
		bool hle_ok = !access(touchhle_dir(), F_OK);
		bool space_ok = statvfs(hle_ok ? touchhle_dir() : "/", &v) != 0 ||
				(uint64_t)v.f_bavail * v.f_frsize >= ipa_cur.unpacked_bytes + (4ULL << 20);

		if (hle_ok && space_ok)
			m3_button(ipa_btn_row, ipa_cur.already_installed ? "Reinstall" : "Install to touchHLE",
				  true, ipa_install_cb, NULL);
	}
}

static void open_ipa_install_re(lv_event_t *e)
{
	const char *base;
	lv_obj_t *scr, *body, *c, *col, *b, *row, *sw;
	char s1[40], line[160];
	struct statvfs v;
	bool hle_ok, space_ok = true;
	uint64_t avail = 0;

	LV_UNUSED(e);
	if (!ipa_src_path[0])
		return;
	nav_mark(open_ipa_install_re, NULL);
	if (!ipa_done_ok && !ipa_installing)
		ipa_inspect(ipa_src_path, &ipa_cur);
	base = strrchr(ipa_src_path, '/');
	base = base ? base + 1 : ipa_src_path;
	hle_ok = !access(touchhle_dir(), F_OK);
	if (!statvfs(hle_ok ? touchhle_dir() : "/", &v)) {
		avail = (uint64_t)v.f_bavail * v.f_frsize;
		if (ipa_cur.valid && avail < ipa_cur.unpacked_bytes + (4ULL << 20))
			space_ok = false;
	}

	body = m3_page("Install app", &scr);
	ipa_page = scr;
	obj_track(&ipa_page);

	/* Header card */
	c = ipa_card = m3_card(body, M.surface_c);
	obj_track(&ipa_card);
	lv_obj_set_height(c, LV_SIZE_CONTENT);
	lv_obj_set_flex_flow(c, LV_FLEX_FLOW_ROW);
	lv_obj_set_flex_align(c, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
	lv_obj_set_style_pad_column(c, 16, 0);
	m3_badge(c, LV_SYMBOL_DOWNLOAD, ipa_cur.valid ? M.primary_c : M.error,
		 ipa_cur.valid ? M.on_primary_c : lv_color_white(), 56);
	col = lv_obj_create(c);
	plain(col);
	lv_obj_set_style_bg_opa(col, LV_OPA_TRANSP, 0);
	lv_obj_set_style_pad_all(col, 0, 0);
	lv_obj_set_height(col, LV_SIZE_CONTENT);
	lv_obj_set_flex_grow(col, 1);
	lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
	lv_obj_set_style_pad_row(col, 2, 0);
	lv_obj_remove_flag(col, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
	b = m3_label(col, ipa_cur.valid ? ipa_cur.bundle_stem : base,
		     &lv_font_montserrat_20, M.on_surface);
	lv_label_set_long_mode(b, LV_LABEL_LONG_DOT);
	lv_obj_set_width(b, lv_pct(100));
	b = m3_label(col, base, &lv_font_montserrat_12, M.on_surface_v);
	lv_label_set_long_mode(b, LV_LABEL_LONG_DOT);
	lv_obj_set_width(b, lv_pct(100));
	if (!ipa_cur.valid) {
		b = m3_label(col, ipa_cur.has_traversal ? "Unsafe archive paths" :
			     "Not a valid iOS .ipa archive", &lv_font_montserrat_14, M.error);
	} else if (!hle_ok) {
		b = m3_label(col, "touchHLE folder not found", &lv_font_montserrat_14, M.error);
	} else if (!space_ok) {
		b = m3_label(col, "Not enough free storage", &lv_font_montserrat_14, M.error);
	} else if (ipa_cur.already_installed) {
		b = m3_label(col, "Already installed (will replace)", &lv_font_montserrat_14, M.primary);
	} else {
		b = m3_label(col, "Ready to install to touchHLE", &lv_font_montserrat_14, M.on_surface_v);
	}
	lv_label_set_long_mode(b, LV_LABEL_LONG_WRAP);
	lv_obj_set_width(b, lv_pct(100));

	if (ipa_cur.valid) {
		c = m3_card(body, M.surface_c);
		lv_obj_set_style_pad_all(c, 4, 0);
		lv_obj_set_flex_flow(c, LV_FLEX_FLOW_COLUMN);
		storage_fmt(s1, sizeof(s1), ipa_cur.file_bytes, "");
		m3_row_ex(c, LV_SYMBOL_FILE, M.secondary_c, M.on_secondary_c,
			  "Archive size", s1, NULL, NULL, NULL, false);
		storage_fmt(s1, sizeof(s1), ipa_cur.unpacked_bytes, "");
		snprintf(line, sizeof(line), "%s (%s)", s1, ipa_cur.bundle_dir);
		m3_row_ex(c, LV_SYMBOL_SD_CARD, M.primary_c, M.on_primary_c,
			  "Unpacked size", line, NULL, NULL, NULL, false);
		if (avail) {
			storage_fmt(s1, sizeof(s1), avail, " free");
			m3_row_ex(c, LV_SYMBOL_DRIVE, M.secondary_c, M.on_secondary_c,
				  "Storage available", s1, NULL, NULL, NULL, false);
		}
		row = m3_row_ex(c, LV_SYMBOL_TRASH, M.secondary_c, M.on_secondary_c,
				"Delete .ipa after install", "Free space once unpacked",
				NULL, NULL, NULL, false);
		sw = ios_switch(lv_switch_create(row));
		if (ipa_del_after)
			lv_obj_add_state(sw, LV_STATE_CHECKED);
		lv_obj_add_event_cb(sw, ipa_del_sw_cb, LV_EVENT_VALUE_CHANGED, NULL);
	}

	ipa_btn_row = lv_obj_create(body);
	obj_track(&ipa_btn_row);
	lv_obj_remove_style_all(ipa_btn_row);
	lv_obj_set_size(ipa_btn_row, lv_pct(100), LV_SIZE_CONTENT);
	lv_obj_set_flex_flow(ipa_btn_row, LV_FLEX_FLOW_ROW);
	lv_obj_set_style_pad_column(ipa_btn_row, 12, 0);
	lv_obj_set_style_pad_top(ipa_btn_row, 4, 0);
	ipa_rebuild_btns();

	ipa_status_lbl = m3_label(body, ipa_installing ?
				  "Installing to touchHLE... This may take a moment." :
				  ipa_done_ok ? "Installed! Added to Home screen." : "",
				  &lv_font_montserrat_14, M.on_surface_v);
	lv_obj_set_width(ipa_status_lbl, lv_pct(100));
	lv_label_set_long_mode(ipa_status_lbl, LV_LABEL_LONG_WRAP);
	lv_obj_set_style_pad_hor(ipa_status_lbl, 8, 0);
	obj_track(&ipa_status_lbl);

	push(scr);
}

void open_ipa_install(const char *path)
{
	if (!path || !*path)
		return;
	if (!ipa_installing) {
		snprintf(ipa_src_path, sizeof(ipa_src_path), "%s", path);
		ipa_done_ok = false;
		ipa_installed_path[0] = 0;
	}
	open_ipa_install_re(NULL);
}
